const meetingTitle = $('Webhook - Tarefa').first().json.body.meeting_title;

// Data formatada
const createdAt = new Date(
  $('Webhook - Tarefa').first().json.body.created_at
).toLocaleDateString('pt-BR');

// 👉 name da página = título + data (ou só data, se preferir)
const pageName = `${meetingTitle} - ${createdAt}`;
// Se quiser SÓ data, use:
// const pageName = createdAt;

// Duração
const start = new Date(
  $('Webhook - Tarefa').first().json.body.recording_start_time
).getTime();

const end = new Date(
  $('Webhook - Tarefa').first().json.body.recording_end_time
).getTime();

const diffMinutes = Math.floor((end - start) / 60000);
const hours = Math.floor(diffMinutes / 60);
const minutes = diffMinutes % 60;
const duration = hours > 0 ? `${hours}h ${minutes}min` : `${minutes}min`;

// Helpers
const normalizeNewlines = (v) =>
  String(v ?? '')
    .replace(/\r\n/g, '\n')
    .replace(/\u2028|\u2029/g, '\n'); // evita line-separators estranhos

const toJsonSafeString = (v) =>
  normalizeNewlines(v)
    .replace(/\n/g, '\\n') // vira \n literal (sem quebra real)
    .replace(/\t/g, ' ');  // remove tabs

// Participantes: se vier array, transforma em lista markdown
const rawParticipants = $('Code in JavaScript14').first().json.participants

const participantsMd = Array.isArray(rawParticipants)
  ? rawParticipants.map((p) => `- ${String(p).trim()}`).join('\n')
  : normalizeNewlines(rawParticipants)
      .split('\n')
      .map((p) => p.trim())
      .filter(Boolean)
      .map((p) => `- ${p}`)
      .join('\n');

// Resumo e transcrição (normalizados)
const summaryRaw = normalizeNewlines(
  $('Webhook - Tarefa').first().json.body.default_summary?.markdown_formatted ?? ''
).trim();

const transcriptRaw = normalizeNewlines($json.formatted_transcript ?? '').trim();

// Links da gravação
const shareUrl = String($('Webhook - Tarefa').first().json.body.share_url ?? '').trim();

// Formato desejado:
// [https://fathom...](https://fathom...?tab=summary&timestamp=0)
const recordingLink = shareUrl
  ? `[${shareUrl}](${shareUrl}?tab=summary&timestamp=0)`
  : '';

// Monta conteúdo "humano" (multilinha)
const contentMultiline = `# 📌 ${meetingTitle}

---

## 🗓 Informações gerais
**Data:** ${createdAt}  
**Duração:** ${duration}

👥 **Participantes:**
${participantsMd}

---

## 🎥 Gravação da reunião
${recordingLink}

---

## 🧠 Resumo
${summaryRaw}

---

## 📝 Transcrição
${transcriptRaw}
`;

// Converte TUDO para uma string segura p/ JSON (sem quebras reais)
const content = toJsonSafeString(contentMultiline);

return [
  {
    json: {
      payload: {
        name: pageName,
        content_format: 'text/md',
        content,
      }
    }
  }
];

const transcripts = $('Edit Fields3').first().json.transcript;

function shortenName(fullName) {
  const parts = String(fullName || '').split(' ').filter(Boolean);
  if (parts.length === 0) return '';

  const firstName = parts[0].slice(0, 2);
  const lastNamesInitials = parts.slice(1).map(p => p[0]).join('');

  return `${firstName}${lastNamesInitials}`;
}

const namesMap = {};
const participantsSet = new Set();

function toSeconds(value) {
  if (value === null || value === undefined || value === '') return null;

  if (typeof value === 'number') {
    return Number.isFinite(value) ? value : null;
  }

  if (typeof value === 'string') {
    const v = value.trim();

    if (!v) return null;

    if (/^\d+(\.\d+)?$/.test(v)) {
      const num = Number(v);
      return Number.isFinite(num) ? num : null;
    }

    const parts = v.split(':').map(Number);

    if (parts.every(n => Number.isFinite(n))) {
      if (parts.length === 2) {
        const [mm, ss] = parts;
        return mm * 60 + ss;
      }
      if (parts.length === 3) {
        const [hh, mm, ss] = parts;
        return hh * 3600 + mm * 60 + ss;
      }
    }
  }

  return null;
}

function formatTime(seconds) {
  if (seconds === null || seconds === undefined || !Number.isFinite(seconds)) {
    return '';
  }

  const total = Math.floor(seconds);
  const hrs = Math.floor(total / 3600);
  const mins = Math.floor((total % 3600) / 60);
  const secs = total % 60;

  if (hrs > 0) {
    return `${String(hrs).padStart(2, '0')}:${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
  }

  return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
}

const conversation = transcripts
  .filter(t => t.speaker?.display_name && t.text)
  .map(t => {
    const fullName = t.speaker.display_name;
    participantsSet.add(fullName);

    if (!namesMap[fullName]) {
      namesMap[fullName] = shortenName(fullName);
    }

    const shortName = namesMap[fullName];

    const rawTime =
      t.start ??
      t.start_time ??
      t.timestamp ??
      t.offset ??
      t.time ??
      t.startTime ??
      null;

    const time = formatTime(toSeconds(rawTime));
    const text = String(t.text).trim();

    return time
      ? `[${time}] ${shortName}: ${text}`
      : `${shortName}: ${text}`;
  })
  .join('\n');

const conversation_length = conversation.length;
const participants = Array.from(participantsSet).join('\n');
const participants_short = Array.from(participantsSet)
  .map(name => namesMap[name])
  .join('\n');

return [
  {
    json: {
      conversation,
      conversation_length,
      names_map: namesMap,
      participants,
      participants_short,
      participants_qtd: participantsSet.size
    }
  }
];

const transcript = $('Webhook - Tarefa').first().json.body.transcript;

if (!Array.isArray(transcript)) {
  return [
    {
      json: {
        formatted_transcript: ''
      }
    }
  ];
}

const blocks = [];
let current = null;

for (const item of transcript) {
  const speaker = item.speaker?.display_name || 'Participante';
  const text = item.text || '';
  const timestamp = item.timestamp || '';

  if (!current || current.speaker !== speaker) {
    if (current) blocks.push(current);
    current = {
      speaker,
      timestamp,
      text: [text]
    };
  } else {
    current.text.push(text);
  }
}

if (current) blocks.push(current);

const formattedTranscript = blocks
  .map(
    b =>
      `**${b.speaker}** (${b.timestamp})  \n${b.text.join(' ')}`
  )
  .join('\n\n');

return [
  {
    json: {
      formatted_transcript: formattedTranscript
    }
  }
];

